#include <stdio.h>

int main() {
    int x[6];
    int sum = 0;

    for (int i = 0; i < 6; i++) {
        scanf("%d", &x[i]);
        sum += x[i];
    }

    if (sum % 3 != 0) {
        printf("N\n");
        return 0;
    }

    int target = sum / 3;
    int hasSingle = 0;

    for (int i = 0; i < 6; i++) {
        if (x[i] == target) {
            hasSingle = 1;
            break;
        }
    }

    int hasPair = 0;
    for (int i = 0; i < 6; i++) {
        for (int j = i + 1; j < 6; j++) {
            if (x[i] + x[j] == target) {
                hasPair = 1;
            }
        }
    }

    if (hasSingle && hasPair) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    return 0;
}
